// Draw an atmospheric hand-painted pixel-art battlefield.
function draw(){const sx=canvas.width/W,sy=canvas.height/H;ctx.setTransform(sx,0,0,sy,0,0);ctx.clearRect(0,0,W,H);const px=player.x,py=player.y;cam.x=clamp(px-W*.48,0,world.w-W);cam.y=clamp(py-H*.52,0,world.h-H);ctx.save();ctx.translate(-cam.x,-cam.y);
// Mud, grass and mottled terrain
ctx.fillStyle='#30372b';ctx.fillRect(0,0,world.w,world.h);for(let i=0;i<620;i++){let x=(i*173+37)%world.w,y=(i*311+91)%world.h;ctx.fillStyle=i%3?'#3b4332':'#4a4934';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,8+(i%17),3+(i%6),i*.7,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// Road
ctx.fillStyle='#4b4738';ctx.fillRect(26,780,459,86);ctx.fillRect(370,595,115,270);ctx.fillStyle='#665b42';ctx.globalAlpha=.3;for(let i=0;i<25;i++)ctx.fillRect(45+i*18,793+(i%4)*15,7,3);ctx.globalAlpha=1;
// Areas and bunker shading
ctx.fillStyle='#57513a';ctx.fillRect(513,51,482,902);ctx.fillStyle='#383d31';ctx.fillRect(1023,54,627,456);ctx.fillRect(1023,538,627,414);ctx.fillStyle='#696045';ctx.fillRect(1290,55,360,450);
// Walls with bevel
for(const b of walls){ctx.fillStyle='#202820';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#626550';ctx.fillRect(b.x,b.y,b.w,Math.min(7,b.h));ctx.fillStyle='#3d4537';ctx.fillRect(b.x,b.y+b.h-5,b.w,5)}
// Barracks floor details and lamps
for(const x of [560,690,830,930]){ctx.fillStyle='#554f3b';ctx.fillRect(x,215,2,170);ctx.fillStyle='#d2a952';ctx.globalAlpha=.1+.06*Math.sin(worldTime*2+x);ctx.beginPath();ctx.arc(x+30,245,65,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
// crates and tables
for(const b of covers){if(b.type==='truck'){ctx.fillStyle='#202923';roundRect(b.x,b.y,b.w,b.h,7);ctx.fillStyle='#384237';roundRect(b.x+7,b.y+7,b.w-14,b.h-14,4);ctx.fillStyle='#687052';ctx.fillRect(b.x+20,b.y+8,42,18);ctx.fillStyle='#131b18';for(let j=0;j<2;j++){ctx.beginPath();ctx.arc(b.x+19+j*52,b.y+b.h-2,11,0,Math.PI*2);ctx.fill()}}else{ctx.fillStyle='#21271f';ctx.fillRect(b.x+3,b.y+5,b.w,b.h);ctx.fillStyle=b.type==='table'?'#6a5a3e':'#57513a';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#82724b';ctx.fillRect(b.x+3,b.y+3,b.w-6,5);ctx.strokeStyle='#282c22';ctx.lineWidth=2;ctx.strokeRect(b.x+1,b.y+1,b.w-2,b.h-2)}}
// Searchlights: moving low intensity cones
for(const [x,y,a] of [[350,530,0],[765,255,.2],[1200,330,1.7],[1450,700,-1.3]]){let ang=a+Math.sin(worldTime*.45+x)*.45;let radius=255;ctx.fillStyle='#eadb9a';ctx.globalAlpha=.075;ctx.beginPath();ctx.moveTo(x,y);ctx.arc(x,y,radius,ang-.21,ang+.21);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#d3bb6c';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
// Exfil marker / mission objective
if(!dossier){drawMarker(dossierPos.x,dossierPos.y,'DOSYA',worldTime)}else if(bossDead){drawMarker(95,810,'ÇIKIŞ',worldTime)}
// Jeep
ctx.save();ctx.translate(jeep.x,jeep.y);ctx.rotate(jeep.angle);ctx.fillStyle='#1b211a';roundRect(-39,-23,78,46,8);ctx.fillStyle='#4a533a';roundRect(-33,-18,66,36,6);ctx.fillStyle='#8c8a67';ctx.fillRect(0,-14,24,28);ctx.fillStyle='#171d19';ctx.fillRect(-28,-20,17,40);for(const wy of [-22,22])for(const wx of [-24,23]){ctx.fillStyle='#101512';roundRect(wx-7,wy-5,14,10,3)}ctx.fillStyle='#d4c685';ctx.fillRect(34,-13,4,8);ctx.fillRect(34,5,4,8);ctx.restore();
// Guards
for(const g of guards){if(g.hp<=0)continue;drawGuard(g)}
// Boss
if(boss.active&&!bossDead)drawBoss();
// Player
if(!player.inJeep)drawPlayer();
// World grit / fog overlays
ctx.restore();drawHud();if(mode==='play')updateHud()}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawMarker(x,y,label,t){ctx.save();ctx.translate(x,y);let r=20+Math.sin(t*3)*3;ctx.strokeStyle='#e2bb61';ctx.globalAlpha=.7;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(0,0,30,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f0d483';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText('◆',0,4);ctx.fillStyle='#f0dfb1';ctx.fillText(label,0,-34);ctx.restore()}
function drawGuard(g){ctx.save();ctx.translate(g.x,g.y);ctx.rotate(g.face);if(g.state==='search'||g.state==='chase'){ctx.fillStyle='#dd5042';ctx.globalAlpha=.11;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,220,-.52,.52);ctx.closePath();ctx.fill();ctx.globalAlpha=1}ctx.fillStyle='#151a15';ctx.beginPath();ctx.ellipse(0,8,13,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=g.state==='chase'?'#9b4538':'#596349';ctx.fillRect(-7,-8,14,19);ctx.fillStyle='#b9a875';ctx.beginPath();ctx.arc(0,-12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#292d23';ctx.fillRect(2,-3,19,4);ctx.fillStyle='#ddd0ac';ctx.fillRect(4,-16,3,2);if(g.state==='search'||g.state==='chase'){ctx.fillStyle='#df5d4c';ctx.beginPath();ctx.arc(0,-24,3+Math.sin(worldTime*8)*1.1,0,Math.PI*2);ctx.fill()}if(g.stun>0){ctx.fillStyle='#f0cf75';ctx.fillText('✦',-4,-28)}ctx.restore()}
function drawBoss(){ctx.save();ctx.translate(boss.x,boss.y);ctx.rotate(boss.face);ctx.fillStyle='#161a16';ctx.beginPath();ctx.ellipse(0,9,17,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#292e27';ctx.fillRect(-10,-11,20,25);ctx.fillStyle='#323a30';ctx.fillRect(-9,-12,18,7);ctx.fillStyle='#b7a16d';ctx.beginPath();ctx.arc(0,-15,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1d211c';ctx.beginPath();ctx.moveTo(-8,-20);ctx.lineTo(-7,-29);ctx.lineTo(7,-29);ctx.lineTo(8,-20);ctx.closePath();ctx.fill();ctx.fillRect(-12,-22,24,3);ctx.fillStyle='#171b17';ctx.fillRect(5,-3,23,4);ctx.restore();ctx.fillStyle='#23271f';ctx.fillRect(boss.x-23,boss.y-42,46,5);ctx.fillStyle='#ce5949';ctx.fillRect(boss.x-22,boss.y-41,44*boss.hp/boss.max,3);ctx.fillStyle='#e7d6b3';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText('HEDEF',boss.x,boss.y-48)}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.face);ctx.fillStyle='#121711';ctx.beginPath();ctx.ellipse(0,9,13,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=player.crouch?'#34483c':'#405345';ctx.fillRect(-7,-8,14,18);ctx.fillStyle='#c2a982';ctx.beginPath();ctx.arc(0,-12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222820';ctx.fillRect(-7,-16,14,4);ctx.fillStyle='#171d18';ctx.fillRect(1,-3,20,4);ctx.fillStyle='#d9bf76';ctx.fillRect(19,-4,3,6);if(player.invul>0&&Math.floor(worldTime*18)%2===0){ctx.strokeStyle='#eee0a1';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function drawHud(){// subtle coordinate/cinematic grain
const grad=ctx.createRadialGradient(W/2,H/2,80,W/2,H/2,H*.75);grad.addColorStop(0,'#0000');grad.addColorStop(1,'#070a08a6');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
// compass hint
ctx.fillStyle='#e9d8b2aa';ctx.font='10px ui-sans-serif';ctx.textAlign='center';ctx.fillText(dossier?'HEDEF: SIĞINAK':'HEDEF: KARARGÂH',W/2,38);
if(player.inJeep){ctx.fillStyle='#d6c48c';ctx.font='bold 11px system-ui';ctx.fillText('JEEP · MOTOR SESİ DÜŞMANLARI ÇEKER',W/2,H-25)} }

