if(player.inJeep){ctx.fillStyle='#d6c48c';ctx.font='bold 11px system-ui';ctx.fillText('JEEP · MOTOR SESİ DÜŞMANLARI ÇEKER',W/2,H-25)} }

function update(dt){worldTime+=dt;if(mode!=='play')return;player.fireCd=Math.max(0,player.fireCd-dt);player.invul=Math.max(0,player.invul-dt);if(player.reload>0){player.reload-=dt;if(player.reload<=0){let take=Math.min(8-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;say('Şarjör dolduruldu.')}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
let mx=touchMove.x,my=touchMove.y;if(keys.has('KeyW')||keys.has('ArrowUp'))my--;if(keys.has('KeyS')||keys.has('ArrowDown'))my++;if(keys.has('KeyA')||keys.has('ArrowLeft'))mx--;if(keys.has('KeyD')||keys.has('ArrowRight'))mx++;let mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}player.crouch=keys.has('ShiftLeft')||keys.has('ShiftRight')||$('#crouchBtn').classList.contains('active');let speed=player.inJeep?195:(player.crouch?70:125);if(mag>.08){moveBody(player,mx*speed*dt,my*speed*dt,player.inJeep?18:12);if(!mouse.active)player.face=Math.atan2(my,mx)}if(player.inJeep){jeep.x=player.x;jeep.y=player.y;jeep.angle=player.face;if(mag>.25)alarm=Math.max(alarm,.12)}
if(mouse.active&&!player.inJeep){let wx=mouse.x+cam.x,wy=mouse.y+cam.y;player.face=Math.atan2(wy-player.y,wx-player.x)}
const firing=keys.has('Space')||touchFire;if(firing)shoot();
let near=dist(player,jeep)<52,nearDesk=!dossier&&dist(player,dossierPos)<54,nearBoss=dossier&&boss.active&&dist(player,boss)<58,nearExit=bossDead&&dist(player,{x:95,y:810})<58;let action=nearDesk?'DOSYAYI AL':nearBoss?'HEDEFİ ETKİSİZLEŞTİR':nearExit?'BÖLGEDEN AYRIL':near?'JEEPE BİN / İN':'ETKİLEŞ';$('#actionBtn span').textContent=action;
if(keys.has('KeyE')){keys.delete('KeyE');interact()}
// Enemy sight, searches and combat
