function reload(){if(player.reload<=0&&player.ammo<8&&player.reserve>0){player.reload=1.05;say('Şarjör değiştiriliyor…')}}

// Pointer aiming on desktop; touch joystick/actions for phone and tablet.
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width*W;mouse.y=(e.clientY-r.top)/r.height*H;mouse.active=true}});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&mode==='play'){const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width*W;mouse.y=(e.clientY-r.top)/r.height*H;mouse.active=true;shoot()}});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='KeyR')reload();if(e.code==='KeyE')interact()});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
const stick=$('#stick'),knob=$('#knob');let stickId=null;function stickUpdate(e){let r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,d=Math.hypot(dx,dy);if(d>max){dx*=max/d;dy*=max/d}touchMove={x:dx/max,y:dy/max};knob.style.transform=`translate(${dx}px,${dy}px)`}stick.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(stickId);stickUpdate(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickUpdate(e)});function stickEnd(e){if(e.pointerId===stickId){stickId=null;touchMove={x:0,y:0};knob.style.transform=''}}stick.addEventListener('pointerup',stickEnd);stick.addEventListener('pointercancel',stickEnd);
const crouch=$('#crouchBtn');crouch.addEventListener('pointerdown',e=>{e.preventDefault();crouch.classList.toggle('active')});$('#actionBtn').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('#reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload()});const fire=$('#fireBtn');fire.addEventListener('pointerdown',e=>{e.preventDefault();touchFire=true;fire.classList.add('active');shoot()});for(const ev of ['pointerup','pointercancel','pointerleave'])fire.addEventListener(ev,()=>{touchFire=false;fire.classList.remove('active')});
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
showCard('menu');requestAnimationFrame(frame);
})();
</script>
</body>
</html>

