import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3000');
await page.locator('#startBtn').click();
const hud=()=>page.locator('#ammoNum').innerText();
console.log('started',await hud());
await page.keyboard.down('KeyW'); await page.waitForTimeout(1000); await page.keyboard.up('KeyW');
await page.keyboard.down('KeyD'); await page.waitForTimeout(2200); await page.keyboard.up('KeyD');
await page.keyboard.down('KeyW'); await page.waitForTimeout(150); await page.keyboard.up('KeyW');
console.log('action near tank?',await page.locator('#actionBtn span').innerText());
await page.keyboard.press('KeyE'); await page.waitForTimeout(200);
console.log('entered tank HUD',await hud(),'toast',await page.locator('#toast').innerText());
await page.keyboard.down('KeyD'); await page.waitForTimeout(500); await page.keyboard.up('KeyD');
await page.keyboard.press('Space');
console.log('fired tank HUD',await hud());
await page.waitForTimeout(1900);
console.log('after projectile toast',await page.locator('#toast').innerText(),'errors',errors);
await page.keyboard.press('KeyE'); await page.waitForTimeout(150);
console.log('exit vehicle action',await page.locator('#actionBtn span').innerText(),'toast',await page.locator('#toast').innerText());
await page.locator('#audioBtn').click();
console.log('audio toggle',await page.locator('#audioBtn').getAttribute('aria-pressed'));
await page.screenshot({path:'/tmp/opencode/captures/interaction-desktop.png'});
await browser.close();
EOF

